class Solution(object):
    def tilingRectangle(self, n, m):
        """
        :type n: int
        :type m: int
        :rtype: int
        """
        def dfs(x, y, cnt):
            if cnt >= self.ans:
                return
            if x >= n:
                self.ans = cnt
                return
            if y >= m:
                dfs(x + 1, 0, cnt)
                return
            if rect[x][y]:
                dfs(x, y + 1, cnt)
                return
            cur_len = min(n - x, m - y)
            while cur_len >= 1 and not is_available(x, y, cur_len):
                cur_len -= 1
            while cur_len >= 1:
                fill_up(x, y, cur_len, True)
                dfs(x, y + cur_len, cnt + 1)
                fill_up(x, y, cur_len, False)
                cur_len -= 1

        def is_available(x, y, k):
            for i in range(k):
                for j in range(k):
                    if rect[x + i][y + j] == True:
                        return False
            return True

        def fill_up(x, y, k, val):
            for i in range(k):
                for j in range(k):
                    rect[x + i][y + j] = val

        self.ans = m * n
        rect = [[False] * m for _ in range(n)]
        dfs(0, 0, 0)
        return self.ans
